--
-- TOC entry 231 (class 1259 OID 17095)
-- Name: career_features; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.career_features AS
 SELECT l.leader_id,
    count(DISTINCT c.seq) AS total_positions,
    count(DISTINCT c.province) AS provinces_served,
    count(DISTINCT c.department) AS departments_served,
    min(c.start_year) AS career_start_year,
    max(c.end_year) AS career_end_year,
    (max(c.end_year) - min(c.start_year)) AS career_span_years
   FROM (public.leaders l
     LEFT JOIN public.career_history c ON ((l.leader_id = c.leader_id)))
  GROUP BY l.leader_id;


